{(event) => {
        if (platform === "ios") {
          event.currentTarget.href = iosAppEntry(location.pathname + location.search + location.hash, location.hostname) ?? iosAppEntry(en ? "/en" : "/", location.hostname) ?? APP_STORES.ios;
        } else if (androidAction) {
